class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums.length < 4) return result;

        Arrays.sort(nums);
        int n = nums.length;

        for (int i = 0; i < n - 3; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;

            for (int j = i + 1; j < n - 2; j++) {
                if (j > i + 1 && nums[j] == nums[j - 1]) continue;

                int left = j + 1, right = n - 1;
                long remain = (long) target - nums[i] - nums[j];

                while (left < right) {
                    long sum = (long) nums[left] + nums[right];
                    if (sum == remain) {
                        result.add(Arrays.asList(nums[i], nums[j], nums[left], nums[right]));
                        while (left < right && nums[left] == nums[left + 1]) left++;
                        while (left < right && nums[right] == nums[right - 1]) right--;
                        left++;
                        right--;
                    } else if (sum < remain) {
                        left++;
                    } else {
                        right--;
                    }
                }
            }
        }

        return result;
    }
}

class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        Arrays.sort(nums);
        return kSum(nums, target, 0, 4);
    }

    private List<List<Integer>> kSum(int[] nums, long target, int start, int k) {
        List<List<Integer>> result = new ArrayList<>();
        if (start >= nums.length) return result;

        if (k == 2) {
            return twoSum(nums, target, start);
        }

        for (int i = start; i < nums.length - k + 1; i++) {
            if (i > start && nums[i] == nums[i - 1]) continue;

            for (List<Integer> subset : kSum(nums, target - nums[i], i + 1, k - 1)) {
                List<Integer> quad = new ArrayList<>();
                quad.add(nums[i]);
                quad.addAll(subset);
                result.add(quad);
            }
        }

        return result;
    }

    private List<List<Integer>> twoSum(int[] nums, long target, int start) {
        List<List<Integer>> result = new ArrayList<>();
        int left = start, right = nums.length - 1;

        while (left < right) {
            long sum = (long) nums[left] + nums[right];
            if (sum == target) {
                result.add(Arrays.asList(nums[left], nums[right]));
                while (left < right && nums[left] == nums[left + 1]) left++;
                while (left < right && nums[right] == nums[right - 1]) right--;
                left++;
                right--;
            } else if (sum < target) {
                left++;
            } else {
                right--;
            }
        }

        return result;
    }
}

class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        if (nums.length < 4) return new ArrayList<>();
        Arrays.sort(nums);
        int n = nums.length;
        Map<Long, List<int[]>> pairsBySum = new HashMap<>();
        Set<String> seenPairValues = new HashSet<>();
        Set<List<Integer>> unique = new LinkedHashSet<>();

        for (int c = 2; c < n - 1; c++) {
            int b = c - 1;
            for (int a = 0; a < b; a++) {
                long pairSum = (long) nums[a] + nums[b];
                String pairKey = pairSum + ":" + nums[a] + ":" + nums[b];
                if (seenPairValues.add(pairKey)) {
                    pairsBySum.computeIfAbsent(pairSum, ignored -> new ArrayList<>())
                            .add(new int[] {nums[a], nums[b]});
                }
            }

            for (int d = c + 1; d < n; d++) {
                long needed = (long) target - nums[c] - nums[d];
                List<int[]> pairs = pairsBySum.get(needed);
                if (pairs == null) continue;
                for (int[] pair : pairs) {
                    unique.add(Arrays.asList(pair[0], pair[1], nums[c], nums[d]));
                }
            }
        }

        return new ArrayList<>(unique);
    }
}

class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        TreeMap<Integer, Integer> counts = new TreeMap<>();
        for (int num : nums) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }
        List<Integer> values = new ArrayList<>(counts.keySet());
        List<List<Integer>> result = new ArrayList<>();

        for (int i = 0; i < values.size(); i++) {
            int a = values.get(i);
            for (int j = i; j < values.size(); j++) {
                int b = values.get(j);
                for (int k = j; k < values.size(); k++) {
                    int c = values.get(k);
                    long dLong = (long) target - a - b - c;
                    if (dLong < c || dLong < Integer.MIN_VALUE || dLong > Integer.MAX_VALUE) continue;
                    int d = (int) dLong;
                    if (!counts.containsKey(d)) continue;
                    if (hasEnough(counts, a, b, c, d)) {
                        result.add(Arrays.asList(a, b, c, d));
                    }
                }
            }
        }

        return result;
    }

    private boolean hasEnough(Map<Integer, Integer> counts, int a, int b, int c, int d) {
        Map<Integer, Integer> needed = new HashMap<>();
        needed.put(a, needed.getOrDefault(a, 0) + 1);
        needed.put(b, needed.getOrDefault(b, 0) + 1);
        needed.put(c, needed.getOrDefault(c, 0) + 1);
        needed.put(d, needed.getOrDefault(d, 0) + 1);
        for (Map.Entry<Integer, Integer> entry : needed.entrySet()) {
            if (counts.getOrDefault(entry.getKey(), 0) < entry.getValue()) {
                return false;
            }
        }
        return true;
    }
}
